export function validateRpUsageDay(value: RpUsageDay): string[] {
  const errors: string[] = [];
  if (!isCalendarDate(value.day)) errors.push("day: expected YYYY-MM-DD");
  return errors;
}

export function validateGetApplicationUsageRequest(value: GetApplicationUsageRequest): string[] {
  const errors: string[] = [];
  if (!isCalendarDate(value.firstDay)) errors.push("firstDay: expected YYYY-MM-DD");
  if (!isCalendarDate(value.lastDay)) errors.push("lastDay: expected YYYY-MM-DD");
  return errors;
}

export function validateLocalRpDescriptor(value: LocalRpDescriptor): string[] {
  const errors: string[] = [];
  if (value.signingPublicKey.length !== 32) errors.push("signingPublicKey: length must equal 32");
  if (value.encryptionPublicKey.length !== 32) errors.push("encryptionPublicKey: length must equal 32");
  return errors;
}

export function validateLocalRpCallbackHeader(value: LocalRpCallbackHeader): string[] {
  const errors: string[] = [];
  if (value.ephemeralPublicKey.length !== 32) errors.push("ephemeralPublicKey: length must equal 32");
  if (value.aeadNonce.length !== 12) errors.push("aeadNonce: length must equal 12");
  return errors;
}

export function validateAdminLocalRp(value: AdminLocalRp): string[] {
  const errors: string[] = [];
  if (value.signingPublicKey.length !== 32) errors.push("signingPublicKey: length must equal 32");
  if (value.encryptionPublicKey.length !== 32) errors.push("encryptionPublicKey: length must equal 32");
  return errors;
}

